    static let serviceWorker = #"""
// ClipSync service worker: makes the phone client installable, serves its assets from cache, and
// receives Android "Share → ClipSync" (Web Share Target). Clipboard data and files are never
// cached; only the assets are. Versions are filled in by build.mjs.
const VERSION = 'c40277b1e1f9';
const SHELL_CACHE = `clipsync-shell-${VERSION}`;
const SHARE_CACHE = 'clipsync-share';
const SHELL = [
  '/app.css?v=0a5996355e4b',
  '/app.js?v=aa2c5608fa73',
  '/manifest.webmanifest',
  '/icon.svg',
  '/icon-180.png',
  '/icon-192.png',
  '/icon-512.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL_CACHE).then((cache) => cache.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys
        .filter((key) => key.startsWith('clipsync-shell-') && key !== SHELL_CACHE)
        .map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.method === 'POST' && url.pathname === '/share-target') {
    event.respondWith(receiveShare(request));
    return;
  }
  // Live data (clipboard, pairing, uploads, downloads) always goes to the Mac.
  if (request.method !== 'GET' || url.pathname.startsWith('/api/') || url.pathname.startsWith('/dl/')) return;

  // Leave page loads to the browser: a cached page would hide its certificate warning, the only
  // way past an untrusted certificate, and every call to the Mac would then fail with no way out.
  if (request.mode === 'navigate') return;

  event.respondWith(caches.match(request).then((cached) => cached || fetch(request)));
});

// Android share sheet → ClipSync. The service worker has no access to the device token, so it
// parks the shared items in a cache and hands over to the page (/?shared=1), which sends them.
async function receiveShare(request) {
  const form = await request.formData();
  const cache = await caches.open(SHARE_CACHE);
  for (const key of await cache.keys()) await cache.delete(key);

  let index = 0;
  for (const file of form.getAll('files')) {
    if (!(file instanceof File) || file.size === 0) continue;
    await cache.put(`/shared/file/${index++}`, new Response(file, {
      headers: {
        'Content-Type': file.type || 'application/octet-stream',
        'X-Filename': encodeURIComponent(file.name || 'Shared file'),
      },
    }));
  }
  // Shared links usually arrive as text and/or url; the page title only if there is nothing else.
  const values = ['text', 'url'].map((field) => form.get(field))
    .filter((value) => typeof value === 'string' && value.trim());
  const unique = [...new Set(values.map((value) => value.trim()))];
  const title = form.get('title');
  const text = unique.length ? unique.join('\n') : (typeof title === 'string' ? title.trim() : '');
  if (text) await cache.put('/shared/text', new Response(text));

  return Response.redirect('/?shared=1', 303);
}

// ---------- Notifications (Web Push from the Mac) ----------
// The message usually has no clipboard content (only what kind of item it is); with "Show what was
// copied" on, it has a short preview. Tapping opens ClipSync, which fetches the item from the Mac.
self.addEventListener('push', (event) => {
  let message = {};
  try { message = event.data ? event.data.json() : {}; } catch { /* not JSON */ }
  const from = message.s && message.s !== 'Mac' ? message.s : 'your Mac';
  let title = `New from ${from}`;
  let body = 'Tap to copy it to this phone.';
  if (message.k === 'image') body = 'An image — tap to copy it.';
  if (message.k === 'file') {
    title = `File from ${from}`;
    body = message.n ? `${message.n} — tap to download.` : 'Tap to download it.';
  }
  if (message.t) body = message.t;

  event.waitUntil((async () => {
    // Skip it if ClipSync is already on screen: it syncs by itself.
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    if (windows.some((client) => client.visibilityState === 'visible')) return;
    await self.registration.showNotification(title, {
      body,
      tag: 'clipsync-clipboard',   // one notification, replaced by the newest
      renotify: true,
      icon: '/icon-192.png',
      badge: '/icon-192.png',
      data: { url: '/?from=notification' },
    });
  })());
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const client of windows) {
      if (new URL(client.url).origin === self.location.origin && 'focus' in client) return client.focus();
    }
    return self.clients.openWindow('/?from=notification');
  })());
});
